package com.itsm.changemanagement.exception;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(ApiExceptions.NotFound.class) ResponseEntity<?> nf(RuntimeException e){return err(404,e.getMessage());}@ExceptionHandler(ApiExceptions.Conflict.class)ResponseEntity<?> cf(RuntimeException e){return err(409,e.getMessage());}@ExceptionHandler({ApiExceptions.Invalid.class,IllegalArgumentException.class})ResponseEntity<?> iv(RuntimeException e){return err(400,e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> val(MethodArgumentNotValidException e){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","Validation failed","fields",f));}@ExceptionHandler(Exception.class)
ResponseEntity<?> other(Exception e) {
    e.printStackTrace();
    return err(500, "Unexpected server error: " + e.getClass().getName() + " - " + e.getMessage());
}private ResponseEntity<?> err(int s,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s,"error",m));}}
